const seed = {
  people: [
    {id:'p1', name:'James Ferrett', initials:'JF', roles:['Audio','Camera','Event Lead'], type:'Contractor', rate:32, status:'Active'},
    {id:'p2', name:'Sarah Kim', initials:'SK', roles:['Retail','Volunteer','Setup'], type:'Volunteer', rate:28, status:'Active'},
    {id:'p3', name:'Mike Torres', initials:'MT', roles:['Camera','Setup'], type:'Contractor', rate:30, status:'Active'},
    {id:'p4', name:'Nina Patel', initials:'NP', roles:['Audio','Event Lead'], type:'Employee', rate:34, status:'Active'},
    {id:'p5', name:'Owen Brooks', initials:'OB', roles:['Volunteer','Retail'], type:'Volunteer', rate:22, status:'Active'}
  ],
  events: [
    {id:'e1', name:'Wisconsin Football Event', number:'WF-2408', date:'2026-09-27', start:'15:00', end:'21:00', location:'Camp Randall Stadium', address:'1440 Monroe St, Madison, WI', role:'Audio', status:'Confirmed', pay:192, crew:['p1','p4'], color:'blue', notes:'Check in at Gate 3. Audio load-in is behind the south scoreboard.'},
    {id:'e2', name:'Harvest Market Setup', number:'HM-0918', date:'2026-09-27', start:'08:00', end:'12:00', location:'Monona Terrace', address:'1 John Nolen Dr, Madison, WI', role:'Setup', status:'Confirmed', pay:112, crew:['p2'], color:'gold', notes:'Use the vendor entrance on the east side.'},
    {id:'e3', name:'Community Welcome Desk', number:'CW-0929', date:'2026-09-29', start:'09:00', end:'13:00', location:'Five Points Community Center', address:'123 Main St, Madison, WI', role:'Volunteer', status:'Pending', pay:0, crew:['p5'], color:'green', notes:'Bring a charged tablet for check-in.'}
  ],
  opportunities: [
    {id:'o1', eventId:'e1', role:'Camera Operator', required:2, filled:1, hours:6, rate:30},
    {id:'o2', eventId:'e3', role:'Event Lead', required:1, filled:0, hours:4, rate:34}
  ],
  availability: { unavailable:['2026-09-28','2026-10-12'], tentative:['2026-09-30'] },
  timesheets: [{id:'t1', event:'Summer Block Party', person:'Sarah Kim', date:'2026-09-20', hours:'4.00', rate:28, pay:112, status:'Approved'}]
};
let state = JSON.parse(localStorage.getItem('crewline-state') || 'null') || seed;
const app = document.querySelector('#app');
const fmtDate = (d) => new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(`${d}T12:00:00`));
const money = (n) => n === 0 ? 'Volunteer' : `$${Number(n).toFixed(0)}`;
function save(){ localStorage.setItem('crewline-state', JSON.stringify(state)); }
function initials(name){ return name.split(' ').map(x=>x[0]).join('').slice(0,2); }
function person(id){ return state.people.find(p=>p.id===id); }
function event(id){ return state.events.find(e=>e.id===id); }
function nav(active){ return `<aside class="sidebar"><div class="nav-label">Workspace</div><nav class="nav">${[['schedule','▦','Schedule'],['opportunities','◉','Opportunities'],['people','♧','People'],['availability','◷','Availability'],['timesheets','▤','Timesheets']].map(([id,icon,label])=>`<button class="${active===id?'active':''}" data-route="${id}">${icon}&nbsp;&nbsp;${label}${id==='opportunities'?` <span class="pill gold" style="float:right;padding:3px 6px">2</span>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><strong>Northline Events</strong><br><span class="subtle">5 active people · Central time</span></div></aside>`; }
function bottomNav(active){ return `<nav class="bottom-nav">${[['schedule','⌂','Schedule'],['opportunities','◉','Open'],['people','♧','People'],['availability','◷','Avail.'],['timesheets','≡','More']].map(([id,icon,label])=>`<button class="${active===id?'active':''}" data-route="${id}"><span class="nav-icon">${icon}</span>${label}</button>`).join('')}</nav>`; }
function layout(active, content){ app.innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">C</span> Crewline</div><div class="org">Northline Events&nbsp; · &nbsp;Admin workspace</div><button class="btn small" id="reset" style="background:transparent;color:#fff;border-color:#536079">Reset demo</button></header><div class="layout">${nav(active)}<main class="content">${content}</main></div>${bottomNav(active)}</div>`; document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>render(b.dataset.route)); document.querySelector('#reset').onclick=()=>{localStorage.removeItem('crewline-state'); location.reload();}; }
function schedule(){ const today='2026-09-27'; const upcoming=state.events.filter(e=>e.date>=today); layout('schedule', `<div class="page-head"><div><div class="eyebrow">Sunday, September 27</div><h1>Good morning, James</h1><p class="subtle" style="margin-top:6px">Two confirmed calls today, one open role to fill.</p></div><button class="btn gold" data-action="new-event">+ New event</button></div><div class="grid kpis"><div class="card kpi"><div class="eyebrow">Today</div><strong>2</strong><span class="trend">Both confirmed</span></div><div class="card kpi"><div class="eyebrow">Open positions</div><strong>2</strong><span class="trend" style="color:#8e5b0b">Needs attention</span></div><div class="card kpi"><div class="eyebrow">Estimated pay</div><strong>$304</strong><span class="trend">Across today’s calls</span></div><div class="card kpi"><div class="eyebrow">Timesheets</div><strong>1</strong><span class="trend" style="color:var(--blue)">Awaiting review</span></div></div><div class="grid two"><section class="card"><div class="section-head"><h2>My schedule</h2><button class="btn small ghost">Export .ics</button></div><div class="event-list">${upcoming.map((e,i)=>eventCard(e,i===0?'blue':'gold')).join('')}</div></section><section class="card"><div class="section-head"><h2>Open opportunities</h2><button class="btn small ghost" data-route="opportunities">View all</button></div>${state.opportunities.map(opportunityCard).join('')}</section></div>`); bindActions(); }
function eventCard(e,color){ return `<button class="event-card ${color}" data-event="${e.id}" style="text-align:left"><span class="event-bar"></span><span><span class="event-title">${e.name}</span><span class="event-meta"><span>${fmtDate(e.date)}</span><span>${e.start}–${e.end}</span><span>${e.location}</span></span><span style="display:block;margin-top:9px"><span class="pill ${e.status==='Confirmed'?'green':'gold'}">${e.status}</span> <span class="pill blue">${e.role}</span></span></span><span class="event-side"><strong>${money(e.pay)}</strong><small>estimated pay</small></span></button>`; }
function opportunityCard(o){ const e=event(o.eventId); const pct=Math.min(100,(o.filled/o.required)*100); return `<div class="opportunity"><div class="row"><strong>${o.role}</strong><span class="pill gold">${o.required-o.filled} open</span></div><div class="subtle" style="margin-top:6px">${e.name} · ${fmtDate(e.date)} · ${e.start}–${e.end}</div><div class="progress"><span style="width:${pct}%"></span></div><div class="row" style="margin-top:8px"><span class="subtle">${o.filled} of ${o.required} filled</span><strong>${money(o.hours*o.rate)}</strong></div><div class="actions"><button class="btn small primary" data-accept="${o.id}">Accept</button><button class="btn small" data-decline="${o.id}">Decline</button></div></div>`; }
function opportunities(){ layout('opportunities', `<div class="page-head"><div><div class="eyebrow">Open shifts</div><h1>Opportunities</h1><p class="subtle" style="margin-top:6px">Qualified people can raise their hand. A scheduler approves the final assignment.</p></div></div><div class="grid two"><section class="card"><div class="section-head"><h2>Available to you</h2><span class="pill gold">2 open</span></div>${state.opportunities.map(opportunityCard).join('')}</section><section class="card"><div class="section-head"><h2>How coverage works</h2></div><div class="stack"><div class="row"><span class="pill blue">1</span><span style="flex:1">You accept an opportunity</span></div><div class="row"><span class="pill blue">2</span><span style="flex:1">The scheduler reviews conflicts and approves</span></div><div class="row"><span class="pill blue">3</span><span style="flex:1">Your schedule and calendar update once approved</span></div></div></section></div>`); bindActions(); }
function eventDetail(id){ const e=event(id); const crew=e.crew.map(person).filter(Boolean); return layout('schedule', `<button class="btn small ghost" data-route="schedule" style="margin-bottom:18px">← Back to schedule</button><div class="detail-hero"><div class="eyebrow" style="color:#f0b34b">${e.number} · ${e.status}</div><div class="row"><div><h1>${e.name}</h1><p class="subtle" style="margin-top:8px">${fmtDate(e.date)} · ${e.start}–${e.end}</p></div><span class="pill green">${e.role}</span></div><div class="info-grid"><div><div class="info-label">Location</div><div class="info-value">${e.location}</div><div class="subtle">${e.address}</div></div><div><div class="info-label">Estimated pay</div><div class="info-value">${money(e.pay)}</div><div class="subtle">6 hrs · $32/hr</div></div></div></div><div class="detail-grid"><section class="card"><div class="section-head"><h2>Event details</h2><button class="btn small">Add to calendar</button></div><p class="subtle">${e.notes}</p><div style="margin-top:22px"><div class="section-head"><h2>Crew / team</h2><span class="pill blue">${crew.length} assigned</span></div><div class="crew-list">${crew.map(p=>`<div class="row"><div class="person"><div class="avatar">${p.initials}</div><div class="person-info"><strong>${p.name}</strong><span>${p.roles.join(' · ')}</span></div></div><button class="btn small">Message</button></div>`).join('')}</div></div></section><aside class="card"><div class="section-head"><h2>Timesheet</h2><span class="pill green">Ready after call</span></div><div class="info-grid" style="grid-template-columns:1fr"><div><div class="info-label">Scheduled</div><div class="info-value">${e.start}–${e.end} · 6 hours</div></div><div><div class="info-label">Minimum call</div><div class="info-value">4 hours</div></div><div><div class="info-label">Estimated pay</div><div class="info-value">${money(e.pay)}</div><div class="subtle">Paid hours use the greater of actual or minimum call.</div></div></div><button class="btn primary" style="width:100%;margin-top:20px">Submit hours after event</button></aside></div>`); }
function people(){ return layout('people', `<div class="page-head"><div><div class="eyebrow">Directory & roles</div><h1>People</h1><p class="subtle" style="margin-top:6px">Search by name or role. Each person can hold multiple roles.</p></div><div><button class="btn" style="margin-right:8px">Import CSV</button><button class="btn primary">+ Add person</button></div></div><div class="card" style="margin-bottom:18px"><input id="person-search" placeholder="Search people or roles…" style="width:100%;border:0;outline:0;font-size:1rem" /></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Roles</th><th>Type</th><th>Default rate</th><th>Status</th></tr></thead><tbody id="people-table">${peopleRows(state.people)}</tbody></table></div><div class="card" style="margin-top:18px"><div class="section-head"><h2>Active roles</h2><button class="btn small">+ New role</button></div><div>${['Audio','Camera','Event Lead','Retail','Setup','Volunteer'].map(r=>`<span class="role-tag">${r}</span>`).join('')}</div></div>`); document.querySelector('#person-search').oninput=(e)=>{ const q=e.target.value.toLowerCase(); document.querySelector('#people-table').innerHTML=peopleRows(state.people.filter(p=>(p.name+' '+p.roles.join(' ')).toLowerCase().includes(q))); }; }
function peopleRows(list){ return list.map(p=>`<tr><td><div class="person"><div class="avatar">${p.initials}</div><div class="person-info"><strong>${p.name}</strong><span>${p.id==='p1'?'james@northline.test':p.name.toLowerCase().replace(' ','@')+'.test'}</span></div></div></td><td>${p.roles.map(r=>`<span class="role-tag">${r}</span>`).join('')}</td><td>${p.type}</td><td>${money(p.rate)}/hr</td><td><span class="pill green">${p.status}</span></td></tr>`).join('') || '<tr><td colspan="5" class="subtle">No people match that search.</td></tr>'; }
function availability(){ const days=['2026-09-27','2026-09-28','2026-09-29','2026-09-30','2026-10-01','2026-10-02','2026-10-03']; return layout('availability', `<div class="page-head"><div><div class="eyebrow">Your availability</div><h1>Availability</h1><p class="subtle" style="margin-top:6px">Schedulers see this before assigning you. You can still work more than one event in a day when times do not overlap.</p></div><button class="btn primary" id="add-blackout">+ Add dates</button></div><div class="card"><div class="section-head"><h2>This week</h2><span class="pill blue">Central time</span></div><div class="availability">${days.map((d,i)=>{const unavailable=state.availability.unavailable.includes(d); const tentative=state.availability.tentative.includes(d); return `<div class="day ${unavailable?'unavailable':''}"><strong>${new Intl.DateTimeFormat('en-US',{weekday:'short'}).format(new Date(`${d}T12:00:00`))}</strong><span>${new Date(`${d}T12:00:00`).getDate()}</span><button data-day="${d}">${unavailable?'Unavailable':tentative?'Tentative':'Available'}</button></div>`}).join('')}</div></div><div class="grid two" style="margin-top:18px"><section class="card"><div class="section-head"><h2>Upcoming blackout dates</h2><span class="pill red">2 unavailable</span></div><div class="stack"><div class="row"><div><strong>Sep 28</strong><div class="subtle">All day</div></div><span class="pill red">Unavailable</span></div><div class="row"><div><strong>Oct 12–15</strong><div class="subtle">All day</div></div><span class="pill red">Unavailable</span></div></div></section><section class="card"><div class="section-head"><h2>Scheduler view</h2></div><p class="subtle">When you are unavailable, Crewline flags the conflict. Admins can still override it with an audit note.</p></section></div>`); document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{const d=b.dataset.day; const i=state.availability.unavailable.indexOf(d); if(i>=0) state.availability.unavailable.splice(i,1); else state.availability.unavailable.push(d); save(); availability();}); document.querySelector('#add-blackout').onclick=()=>toast('Date range picker is next in the prototype backlog.'); }
function timesheets(){ return layout('timesheets', `<div class="page-head"><div><div class="eyebrow">Pay & approvals</div><h1>Timesheets</h1><p class="subtle" style="margin-top:6px">Review submitted hours, minimum calls and estimated versus approved pay.</p></div><button class="btn">Export CSV</button></div><div class="grid kpis"><div class="card kpi"><div class="eyebrow">Awaiting approval</div><strong>1</strong><span class="trend" style="color:#8e5b0b">Needs review</span></div><div class="card kpi"><div class="eyebrow">Approved this week</div><strong>$112</strong><span class="trend">1 timesheet</span></div><div class="card kpi"><div class="eyebrow">Minimum calls</div><strong>4.0h</strong><span class="trend">Applied when needed</span></div><div class="card kpi"><div class="eyebrow">Payroll status</div><strong>Draft</strong><span class="trend" style="color:var(--blue)">Export when ready</span></div></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Event</th><th>Date</th><th>Hours</th><th>Rate</th><th>Total pay</th><th>Status</th></tr></thead><tbody>${state.timesheets.map(t=>`<tr><td><strong>${t.person}</strong></td><td>${t.event}</td><td>${fmtDate(t.date)}</td><td>${t.hours}</td><td>$${t.rate}/hr</td><td><strong>$${t.pay}</strong></td><td><span class="pill green">${t.status}</span></td></tr>`).join('')}</tbody></table></div>`); }
function toast(message){ const el=document.createElement('div'); el.className='toast'; el.textContent=message; document.body.append(el); setTimeout(()=>el.remove(),2600); }
function bindActions(){ document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>eventDetail(b.dataset.event)); document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{ const o=state.opportunities.find(x=>x.id===b.dataset.accept); try { await fetch(`/api/opportunities/${o.id}/respond`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({person_id:'p1',response:'interested'})}); } catch {} o.filled=Math.min(o.required,o.filled+1); save(); toast('Interest sent to the scheduler.'); opportunities(); }); document.querySelectorAll('[data-decline]').forEach(b=>b.onclick=()=>{ b.closest('.opportunity').remove(); toast('Opportunity declined.'); }); document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>render(b.dataset.route)); document.querySelectorAll('[data-action="new-event"]').forEach(b=>b.onclick=()=>toast('Event creation form is the next admin flow to wire to D1.')); }
function render(route){ ({schedule,opportunities,people,availability,timesheets}[route]||schedule)(); }
async function hydrate(){ try { const response=await fetch('/api/bootstrap'); if(response.ok){ state=await response.json(); localStorage.setItem('crewline-state',JSON.stringify(state)); } } catch {} render('schedule'); }
hydrate();
